883	// Type dispatch macro for generic field-based comparison.
884	// Saves and resets transparent_depth_ to 0 before entering EqualWithFields so that
885	// field names of this (non-transparent) node are always pushed into the path, even
886	// when Equal() is called recursively from within a transparent container's field visit.
887	#define EQUAL_DISPATCH(Type)                                             \
888	  if (auto lhs_##Type = As<Type>(lhs)) {                                 \
889	    auto rhs_##Type = As<Type>(rhs);                                     \
890	    node_type_stack_.emplace_back(#Type);                                \
891	    int saved_depth = transparent_depth_;                                \
892	    transparent_depth_ = 0;                                              \
893	    bool result = rhs_##Type && EqualWithFields(lhs_##Type, rhs_##Type); \
894	    transparent_depth_ = saved_depth;                                    \
895	    node_type_stack_.pop_back();                                         \
896	    return result;                                                       \
897	  }
