899	// Dispatch macro for transparent container nodes (Program, SeqStmts).
900	// Increments transparent_depth_ so that their field names are suppressed in the path,
901	// allowing vector/map element accessors ([i] / ['key']) to attach directly to the
902	// parent field name: e.g., body[1] instead of body.stmts[1].
903	#define EQUAL_DISPATCH_TRANSPARENT(Type)                                 \
904	  if (auto lhs_##Type = As<Type>(lhs)) {                                 \
905	    transparent_depth_++;                                                \
906	    auto rhs_##Type = As<Type>(rhs);                                     \
907	    node_type_stack_.emplace_back(#Type);                                \
908	    bool result = rhs_##Type && EqualWithFields(lhs_##Type, rhs_##Type); \
909	    node_type_stack_.pop_back();                                         \
910	    transparent_depth_--;                                                \
911	    return result;                                                       \
912	  }
