914	template <bool AssertMode>
915	bool StructuralEqualImpl<AssertMode>::Equal(const IRNodePtr& lhs, const IRNodePtr& rhs) {
916	  if (lhs.get() == rhs.get()) return true;
917	
918	  if (!lhs || !rhs) {
919	    if constexpr (AssertMode) ThrowMismatch("One node is null, the other is not", lhs, rhs);
920	    return false;
921	  }
922	
923	  if (lhs->TypeName() != rhs->TypeName()) {
924	    if constexpr (AssertMode) {
925	      std::ostringstream msg;
926	      msg << "Node type mismatch (" << lhs->TypeName() << " != " << rhs->TypeName() << ")";
927	      ThrowMismatch(msg.str(), lhs, rhs);
928	    }
929	    return false;
930	  }
931	
932	  // Check MemRef before IterArg and Var (MemRef inherits from Var)
933	  if (auto lhs_memref = As<MemRef>(lhs)) {
934	    auto rhs_memref = std::static_pointer_cast<const MemRef>(rhs);
935	    bool result = rhs_memref && EqualMemRef(lhs_memref, rhs_memref);
936	    return result;
937	  }
938	
939	  // Check IterArg before Var (IterArg inherits from Var)
940	  if (auto lhs_iter = As<IterArg>(lhs)) {
941	    bool result = EqualIterArg(lhs_iter, std::static_pointer_cast<const IterArg>(rhs));
942	    return result;
943	  }
944	
945	  // Check WindowBuffer before Var (WindowBuffer inherits from Var)
946	  if (auto lhs_wb = As<WindowBuffer>(lhs)) {
947	    bool result = EqualWindowBuffer(lhs_wb, std::static_pointer_cast<const WindowBuffer>(rhs));
948	    return result;
949	  }
950	
951	  if (auto lhs_var = As<Var>(lhs)) {
952	    bool result = EqualVar(lhs_var, std::static_pointer_cast<const Var>(rhs));
953	    return result;
954	  }
