53	  IRNodePtr Deserialize(const std::vector<uint8_t>& data) {
54	    id_to_ptr_.clear();
55	
56	    try {
57	      msgpack::object_handle oh = msgpack::unpack(reinterpret_cast<const char*>(data.data()), data.size());
58	      msgpack::object obj = oh.get();
59	      return DeserializeNode(obj, *oh.zone());
60	    } catch (const msgpack::parse_error& e) {
61	      throw RuntimeError(std::string("MessagePack parse error: ") + e.what());
